async function expectedPin(entry){
 assert.ok(entry&&typeof entry.file==='string'&&path.isAbsolute(entry.file)&&Number.isSafeInteger(entry.bytes)&&entry.bytes>0&&/^[a-f0-9]{64}$/.test(entry.sha256));
 assert.ok(!entry.file.split(/[\\/]/).some(p=>p==='..'||/^(private|bin|store|recordings|secrets?)$/i.test(p)));
 const stat=await fs.lstat(entry.file);assert.ok(stat.isFile()&&!stat.isSymbolicLink());assert.equal(path.resolve(await fs.realpath(entry.file)).toLowerCase(),path.resolve(entry.file).toLowerCase());
 const actual=await pin(entry.file);assert.equal(actual.bytes,entry.bytes);assert.equal(actual.sha256,entry.sha256);return actual;
}
async function checkedPreseal(expectedSha){
 const file=path.join(root,'preseal-inputs-finalized-v1.json'),p=await pin(file);assert.equal(p.sha256,expectedSha);const value=await read(file);
 assert.equal(value.state,'formal11-actual-fresh15-bound-not-sealed');assert.equal(value.root,root);assert.equal(value.backendSourceCommit,'5c2e713863d3e9556a92f856b11df2396c73b137');assert.equal(value.backendInputCount,44);assert.equal(value.driverSourceCommit,value.backendSourceCommit);
 assert.equal(value.coreCodeEvidenceCommit,'b84d5d02a8299b6ac36c5e56cb7006f6bc80d3bd');assert.equal(value.driverSourceSha256,'db4e22c69b4f1365d8135023e158f4de00ff35d58330cf7eca98801780e674e7');assert.equal(value.syntax.passed,true);assert.ok(Array.isArray(value.syntax.scripts)&&value.syntax.scripts.length>0);
 assert.ok(Array.isArray(value.files)&&value.files.length>0&&value.files.length<=120);assert.equal(sha(JSON.stringify(value.files)),value.sourceSha256);assert.deepEqual(await pin(fileURLToPath(import.meta.url)),value.rootSealExecutor);
 assert.equal(value.actualProbe15RunId,'1792937158876-b61ec943');assert.deepEqual(value.actualFresh15CompletePassingWindows,[5,5,6]);assert.equal(value.formalCompleteMinuteWindows,146);assert.equal(value.accountPrepared,false);assert.equal(value.realmStarted,false);assert.equal(value.sealed,false);
 for(const entry of value.files)await expectedPin(entry);
 await expectedPin(value.executionPrerequisites);const prerequisites=await read(value.executionPrerequisites.file);assert.equal(prerequisites.runId,value.actualProbe15RunId);assert.equal(prerequisites.capacityAccepted,false);assert.equal(prerequisites.formalRunNotStarted,true);
 for(const entry of [prerequisites.endedVerification,prerequisites.verifierSourceSeal,prerequisites.verifierExecution,prerequisites.verifierExecutionLog,...prerequisites.evidencePins])await expectedPin(entry);
 const verifierSeal=await read(prerequisites.verifierSourceSeal.file);assert.equal(sha(JSON.stringify(verifierSeal.files)),verifierSeal.sourceSha256);assert.ok(verifierSeal.files.length>=2&&verifierSeal.files.length<=128);assert.equal(prerequisites.sourceInputs.length,verifierSeal.files.length);
 for(const entry of prerequisites.sourceInputs){assert.ok(typeof entry.path==='string'&&!path.isAbsolute(entry.path)&&!entry.path.split(/[\\/]/).some(p=>!p||p==='.'||p==='..'));await expectedPin({file:path.join(base,entry.path),bytes:entry.bytes,sha256:entry.sha256});}
 assert.deepEqual(prerequisites.endedVerification,value.actualProbe15Independent);assert.deepEqual(prerequisites.verifierSourceSeal,value.actualProbe15SourceSeal);assert.deepEqual(prerequisites.verifierExecution,value.actualProbe15Execution);
 return{value,pin:p,prerequisites};
}

